SET NAMES utf8mb4;
CREATE TABLE usuarios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL,nombre VARCHAR(120) NOT NULL,password_hash VARCHAR(255) NOT NULL,rol ENUM('AGENTE','SUPERVISOR','ADMIN') NOT NULL DEFAULT 'AGENTE',activo TINYINT(1) NOT NULL DEFAULT 1,password_status ENUM('INITIAL','CHANGED','RESET_BY_ADMIN') NOT NULL DEFAULT 'INITIAL',password_changed_at DATETIME NULL,password_changed_by BIGINT UNSIGNED NULL,last_login_at DATETIME NULL,failed_attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_usuarios_username(username),CONSTRAINT fk_user_changed_by FOREIGN KEY(password_changed_by) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE clientes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tipo_documento VARCHAR(20) NOT NULL,numero_documento VARCHAR(30) NOT NULL,nombres VARCHAR(120),apellidos VARCHAR(120),nombre_completo VARCHAR(240) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'ACTIVO',origen VARCHAR(40) NOT NULL DEFAULT 'SYNC',synced_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cliente_documento(tipo_documento,numero_documento)) ENGINE=InnoDB;
CREATE TABLE operaciones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cliente_id BIGINT UNSIGNED NOT NULL,cedente VARCHAR(100) NOT NULL,cartera VARCHAR(100) NOT NULL,numero_operacion VARCHAR(80) NOT NULL,saldo DECIMAL(14,2) NOT NULL,capital DECIMAL(14,2) NOT NULL,moneda CHAR(3) NOT NULL DEFAULT 'PEN',estado VARCHAR(30) NOT NULL DEFAULT 'ACTIVA',fecha_asignacion DATE NULL,synced_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_op_cliente FOREIGN KEY(cliente_id) REFERENCES clientes(id),UNIQUE KEY uq_operacion(cedente,numero_operacion)) ENGINE=InnoDB;
CREATE TABLE campanas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,cedente VARCHAR(100) NOT NULL,cartera VARCHAR(100) NOT NULL,fecha_inicio DATE NOT NULL,fecha_fin DATE NOT NULL,activa TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE reglas_negociacion (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campana_id BIGINT UNSIGNED NOT NULL,tipo_acuerdo ENUM('CANCELACION','CONVENIO') NOT NULL,descuento_maximo DECIMAL(5,2) NOT NULL DEFAULT 0,monto_minimo DECIMAL(14,2) NULL,inicial_minima_porcentaje DECIMAL(5,2) NOT NULL DEFAULT 0,cuotas_maximas SMALLINT UNSIGNED NOT NULL DEFAULT 1,pagos_mes_maximos SMALLINT UNSIGNED NOT NULL DEFAULT 1,requiere_supervisor TINYINT(1) NOT NULL DEFAULT 0,activo TINYINT(1) NOT NULL DEFAULT 1,CONSTRAINT fk_regla_campana FOREIGN KEY(campana_id) REFERENCES campanas(id)) ENGINE=InnoDB;
CREATE TABLE secuencias_acuerdo (anio SMALLINT UNSIGNED PRIMARY KEY,ultimo INT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE acuerdos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo_acuerdo VARCHAR(30) NOT NULL,cliente_id BIGINT UNSIGNED NOT NULL,operacion_id BIGINT UNSIGNED NOT NULL,campana_id BIGINT UNSIGNED NULL,tipo_acuerdo ENUM('CANCELACION','CONVENIO') NOT NULL,saldo_negociado DECIMAL(14,2) NOT NULL,porcentaje_descuento DECIMAL(5,2) NOT NULL,monto_acordado DECIMAL(14,2) NOT NULL,monto_inicial DECIMAL(14,2) NOT NULL DEFAULT 0,numero_cuotas SMALLINT UNSIGNED NOT NULL,fecha_acuerdo DATE NOT NULL,estado ENUM('BORRADOR','PENDIENTE_APROBACION','APROBADO','VIGENTE','CUMPLIDO','INCUMPLIDO','ANULADO') NOT NULL,creado_por_id BIGINT UNSIGNED NOT NULL,creado_por VARCHAR(40) NOT NULL,aprobado_por BIGINT UNSIGNED NULL,aprobado_at DATETIME NULL,modificado_por BIGINT UNSIGNED NULL,anulado_por BIGINT UNSIGNED NULL,anulado_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_codigo(codigo_acuerdo),CONSTRAINT fk_ac_cliente FOREIGN KEY(cliente_id) REFERENCES clientes(id),CONSTRAINT fk_ac_operacion FOREIGN KEY(operacion_id) REFERENCES operaciones(id),CONSTRAINT fk_ac_creador FOREIGN KEY(creado_por_id) REFERENCES usuarios(id),CONSTRAINT fk_ac_aprobador FOREIGN KEY(aprobado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE cuotas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,acuerdo_id BIGINT UNSIGNED NOT NULL,numero_cuota SMALLINT UNSIGNED NOT NULL,fecha_vencimiento DATE NOT NULL,monto DECIMAL(14,2) NOT NULL,monto_pagado DECIMAL(14,2) NOT NULL DEFAULT 0,fecha_pago DATE NULL,estado ENUM('PENDIENTE','PAGADA','VENCIDA') NOT NULL DEFAULT 'PENDIENTE',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cuota(acuerdo_id,numero_cuota),CONSTRAINT fk_cuota_acuerdo FOREIGN KEY(acuerdo_id) REFERENCES acuerdos(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NULL,username VARCHAR(40) NOT NULL,accion VARCHAR(50) NOT NULL,entidad VARCHAR(50) NOT NULL,entidad_id BIGINT UNSIGNED NULL,valor_anterior JSON NULL,valor_nuevo JSON NULL,ip VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_audit_user FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB;

